package ir

// Replay of testdata/icon-cases.json (the TS⇄Go gate for §3.1 payload rules):
// the fixture is generated by web/src/engine/format/iconParity.test.ts from the
// browser engine, so agreeing here means the CLI refuses exactly the payloads
// the app refuses — no more (a usable icon rejected in the CLI) and no less (a
// hostile payload accepted by the renderer).

import (
	"encoding/json"
	"os"
	"slices"
	"testing"
)

type iconCase struct {
	Name   string   `json:"name"`
	Svg    string   `json:"svg"`
	Issues []string `json:"issues"`
}

type iconBase64Case struct {
	Value     string `json:"value"`
	Canonical bool   `json:"canonical"`
}

type iconFixture struct {
	Version      int              `json:"version"`
	BuiltinIcons []string         `json:"builtinIcons"`
	Base64       []iconBase64Case `json:"base64"`
	Cases        []iconCase       `json:"cases"`
}

func loadIconFixture(t *testing.T) iconFixture {
	t.Helper()
	raw, err := os.ReadFile("../../testdata/icon-cases.json")
	if err != nil {
		t.Fatalf("read icon fixture: %v (regenerate with CORPUS_FIXTURE=1 npx vitest run web/src/engine/format/iconParity.test.ts)", err)
	}
	var fx iconFixture
	if err := json.Unmarshal(raw, &fx); err != nil {
		t.Fatalf("icon fixture json: %v", err)
	}
	if fx.Version != 1 {
		t.Fatalf("fixture version %d, want 1", fx.Version)
	}
	return fx
}

func TestIconIssueParity(t *testing.T) {
	fx := loadIconFixture(t)
	for _, tc := range fx.Cases {
		got := SvgIssues(tc.Svg)
		want := tc.Issues
		if len(got) == 0 && len(want) == 0 {
			continue
		}
		if !slices.Equal(got, want) {
			t.Errorf("%s: issues diverge\n got: %v\nwant: %v", tc.Name, got, want)
		}
	}
}

func TestIconBase64Parity(t *testing.T) {
	fx := loadIconFixture(t)
	for _, tc := range fx.Base64 {
		if got := IsCanonicalBase64(tc.Value); got != tc.Canonical {
			t.Errorf("IsCanonicalBase64(%q) = %v, want %v", tc.Value, got, tc.Canonical)
		}
	}
}

func TestBuiltinIconParity(t *testing.T) {
	fx := loadIconFixture(t)
	names := make([]string, 0, len(BuiltinIconNames))
	for name := range BuiltinIconNames {
		names = append(names, name)
	}
	slices.Sort(names)
	if !slices.Equal(names, fx.BuiltinIcons) {
		t.Fatalf("built-in icon names diverge from the TS registry\n got: %v\nwant: %v", names, fx.BuiltinIcons)
	}
}

func TestSvgIsSafe(t *testing.T) {
	if !SvgIsSafe(`<svg xmlns="http://www.w3.org/2000/svg"><path d="M0 0h1v1z"/></svg>`) {
		t.Fatal("a static path payload must be safe")
	}
	if SvgIsSafe(`<svg><script>alert(1)</script></svg>`) {
		t.Fatal("a script payload must be refused")
	}
}
